escenas.codigo:
@media print {
  @page { size: A4; margin: 14mm; }
  body { background: #fff; }
  .barra-sup, .editor, .lado .acciones {
    display: none !important;
  }
  main { display: block; padding: 0; max-width: none; }
  .lado { position: static; }
  .hoja { box-shadow: none; border-radius: 0; padding: 0; }
  .hoja { font-size: 12px; print-color-adjust: exact; }
}

function duplicar(numero) {
  const orig = leerGuardados().find(p => p.numero === numero);
  if (!orig) return;
  const copia = structuredClone(orig);
  copia.numero = siguienteNumero();
  copia.fecha = hoyISO();
  copia.cliente = { nombre: '', nif: '', contacto: '', dir: '' };
  cargar(copia);
